                      border: 'none',
                      background: scanMethod === 'PHOTO' ? 'var(--brand-primary)' : 'transparent',
                      color: scanMethod === 'PHOTO' ? '#000' : 'var(--text-muted)',
                      cursor: 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      gap: '5px',
